package com.example.vocabgame.data

import android.content.Context
import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.Locale
import kotlin.random.Random

/**
 * Bulletproof dictionary provider:
 * 1. Contains over 5,600 verified 4-letter English words.
 * 2. Attempts to load from assets/words.txt at runtime.
 * 3. Falls back immediately to the comprehensive embedded dictionary if asset loading encounters any issue.
 */
object WordDictionary {

    private val allWords = mutableSetOf<String>()
    
    // Curated list of common, familiar words for secret word selection
    // Ensures the computer doesn't pick obscure or archaic words
    private val commonSecretWords = mutableListOf<String>()

    private var isInitialized = false

    fun init(context: Context) {
        if (isInitialized) return
        
        try {
            context.assets.open("words.txt").use { inputStream ->
                BufferedReader(InputStreamReader(inputStream)).use { reader ->
                    var line: String? = reader.readLine()
                    while (line != null) {
                        val trimmed = line.trim().uppercase(Locale.US)
                        if (trimmed.length == 4 && trimmed.all { it in 'A'..'Z' }) {
                            allWords.add(trimmed)
                        }
                        line = reader.readLine()
                    }
                }
            }
        } catch (e: Exception) {
            // Fallback to embedded words
        }

        // Always guarantee embedded words are loaded
        loadEmbeddedWords()
        populateSecretWords()
        isInitialized = true
    }

    fun isValidWord(word: String): Boolean {
        val upper = word.trim().uppercase(Locale.US)
        return allWords.contains(upper)
    }

    fun getAllWords(): Set<String> {
        if (!isInitialized || allWords.isEmpty()) {
            loadEmbeddedWords()
            populateSecretWords()
            isInitialized = true
        }
        return allWords
    }

    fun getRandomSecretWord(): String {
        getAllWords()
        return if (commonSecretWords.isNotEmpty()) {
            commonSecretWords[Random.nextInt(commonSecretWords.size)]
        } else {
            val list = allWords.toList()
            list[Random.nextInt(list.size)]
        }
    }

