    fun getMeaning(word: String): String {
        val upper = word.trim().uppercase(Locale.US)
        val clue = meaningsMap[upper]
        if (clue != null) return clue

        val firstChar = upper.firstOrNull() ?: 'A'
        val lastChar = upper.lastOrNull() ?: 'Z'
        val vowels = upper.count { it in "AEIOU" }
        return "A meaningful four-letter English vocabulary term starting with '$firstChar' and ending with '$lastChar', comprising $vowels vowel sound${if (vowels > 1) "s" else ""}."
    }
